import { approveQuote } from '../../packages/domain/src/quote-delivery';
import { createCustomerReplyDraft } from '../../apps/desktop/src/renderer/src/features/customer-reply-format';
import { checksQuote } from '../../apps/desktop/src/renderer/src/features/quote-checks.fixture';
const quote = { ...checksQuote, scenario: { ...checksQuote.scenario, locales: ['en', 'de'] }, payment: '30%预付，70%发货前付清', delivery: '收到定金后30天', pending: ['付款条款待确认：已填写但未获人工确认', '交期与交货条件待确认：已填写但未获人工确认'] };
const approval = approveQuote(quote, { approvedBy: 'synthetic-audit', note: 'read-only in-memory probe' }, { id: '00000000-0000-4000-8000-000000000099', approvedAt: '2026-11-01T00:00:00.000Z' });
const english = createCustomerReplyDraft(quote, 'en', []).customerText;
const german = createCustomerReplyDraft(quote, 'de', []).customerText;
const germanDelivery = approval.deliveries.find(d => d.locale === 'de' && d.kind === 'reply')!;
console.log(JSON.stringify({ desktop: { english, german, translatedTemplate: german.includes('Warenzwischensumme') && !german.includes('Goods subtotal'), originalTermsRemain: german.includes(quote.payment) && german.includes(quote.delivery) }, generatedArtifact: { locale: germanDelivery.locale, body: germanDelivery.body, hasHardcodedEnglish: germanDelivery.body.includes('We have prepared the following quotation') && germanDelivery.body.includes('Payment terms: to be confirmed') } }, null, 2));
